vertexShader:
attribute vec3 aC; attribute vec3 aCol; attribute vec2 aSize; varying vec2 vQ; varying vec3 vCol; varying float vF;
#include <fog_pars_vertex>
void main(){
  vec2 d = cameraPosition.xz - aC.xz; float dl = length(d); d = dl > 0.01 ? d / dl : vec2(0.0, 1.0); vec2 n = vec2(-d.y, d.x);
  float L = aSize.x * (0.6 + 0.8 * clamp(dl / 40.0, 0.0, 1.0));
  vec3 wp = vec3(aC.x + d.x * position.y * L + n.x * position.x * aSize.y, aC.y, aC.z + d.y * position.y * L + n.y * position.x * aSize.y);
  vQ = position.xy; vCol = aCol; vec3 vd = normalize(cameraPosition - wp); vF = pow(1.0 - clamp(vd.y, 0.0, 1.0), 2.0);
  vec4 mvPosition = viewMatrix * vec4(wp, 1.0); gl_Position = projectionMatrix * mvPosition;
#include <fog_vertex>
}

fragmentShader:
uniform float uK; varying vec2 vQ; varying vec3 vCol; varying float vF;
#include <fog_pars_fragment>
void main(){ float a = exp(-vQ.x * vQ.x * 4.0) * (1.0 - vQ.y) * smoothstep(0.0, 0.08, vQ.y); gl_FragColor = vec4(vCol * a * vF * uK, 1.0);
#include <tonemapping_fragment>
#include <colorspace_fragment>
#include <fog_fragment>
}
